const popularBrandNames = ["Samsung", "Apple", "Xiaomi", "Tecno", "Infinix", "Oppo", "Vivo", "OnePlus", "HP", "Dell"];
const popularProductVariants = popularBrandNames.flatMap((brand) => {
  const brandProducts = catalogProducts.filter((product) => product.brand === brand).slice(0, 15);
  return brandProducts.map((product, index) => {
    const configuration = product.category === "Phones"
      ? ["6GB RAM / 128GB", "8GB RAM / 256GB", "12GB RAM / 256GB"][index % 3]
      : ["8GB RAM / 256GB SSD", "16GB RAM / 512GB SSD", "32GB RAM / 1TB SSD"][index % 3];
    const configurationSlug = configuration.toLowerCase().replaceAll(" ", "-").replaceAll("/", "-");
    const id = catalogProducts.length + popularBrandNames.indexOf(brand) * brandProducts.length + index + 1;

    return {
      ...product,
      id,
      slug: `${product.slug}-${configurationSlug}`,
      title: `${product.title} (${configuration})`,
      summary: `${product.summary} Listed in the ${configuration} configuration.`,
      price: product.price + (index + 1) * 15000,
      compareAt: product.compareAt + (index + 1) * 15000,
      tags: [...product.tags, configuration],
      isFeatured: false,
      isNew: false,
      isDeal: false,
    };
  });
});

const phoneGalleryImages = [
  "https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1598327105666-5b89351aff97?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1601784551446-20c9e07cdbf0?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1574944985070-8f3ebc6b79d2?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1546868871-7041f2a55e12?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1580910051074-3eb694886b2d?auto=format&fit=crop&w=900&q=80",
];

const laptopGalleryImages = [
  "https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=80",
  "https://images.unsplash.com/photo-1542744094-24638eff58bb?auto=format&fit=crop&w=900&q=80",
];

const catalogWithDrafts = [
  ...catalogProducts,
  ...popularProductVariants,
  ...additionalCatalogProducts,
];
const productSlugs = new Set<string>();
export const products: Product[] = catalogWithDrafts
  .filter((product) => {
    if (productSlugs.has(product.slug)) return false;
    productSlugs.add(product.slug);
    return true;
  })
  .map((product) => {
  const isPhone = product.category === "Phones";
  const gallery = isPhone ? phoneGalleryImages : laptopGalleryImages;
  const isPublished = product.isPublished ?? true;
  const specifications = !isPublished || product.price <= 0
    ? []
    : isPhone
    ? [
        { label: "Brand", value: product.brand },
        { label: "Model", value: product.title },
        { label: "Device type", value: "Smartphone" },
        { label: "Display", value: "Model-specific; check the selected device configuration" },
        { label: "Operating system", value: product.brand === "Apple" ? "iOS; version varies by model" : "Android; version varies by model" },
        { label: "Memory and storage", value: "Varies by model and selected configuration" },
        { label: "Cameras", value: "Camera setup varies by model" },
        { label: "Network and connectivity", value: "Network bands and wireless features vary by model" },
        { label: "Battery and charging", value: "Capacity and charging speed vary by model" },
        { label: "In the box", value: "Contents vary by model and seller configuration" },
      ]
    : [
        { label: "Brand", value: product.brand },
        { label: "Model", value: product.title },
        { label: "Device type", value: "Laptop computer" },
        { label: "Display", value: "Size, resolution, and panel vary by model" },
        { label: "Processor", value: "Processor configuration varies by model" },
        { label: "Memory", value: "RAM configuration varies by model" },
        { label: "Storage", value: "Drive type and capacity vary by model" },
        { label: "Graphics", value: "Integrated or dedicated graphics, depending on configuration" },
        { label: "Operating system", value: "Operating system and version vary by model" },
        { label: "Ports and connectivity", value: "Port selection and wireless features vary by model" },
        { label: "Battery and included accessories", value: "Battery life and box contents vary by model" },
      ];

  return {
    ...product,
    isUkUsed: product.isUkUsed || (product.category === "Laptops" && product.id % 8 === 0),
    isPublished,
    images: isPublished && product.image
      ? [product.image, ...gallery.filter((image) => image !== product.image)].slice(0, 4)
      : [],
    specifications,
  };
});

export const stats = [
  { label: "Happy customers", value: "18K+" },
  { label: "Orders shipped", value: "42K" },
  { label: "Average rating", value: "4.9/5" },
  { label: "Same-day dispatch", value: "96%" },
];

export const featuredProducts = products.filter((product) => product.isFeatured);
export const deals = products.filter((product) => product.isDeal);
export const ukUsedProducts = products.filter((product) => product.isUkUsed);

export function getProductsForCategory(categorySlug: string) {
  switch (categorySlug) {
    case "mobile-phones":
      return products.filter((product) => product.category === "Phones");
    case "laptops-and-computers":
      return products.filter((product) => product.category === "Laptops");
    case "uk-used-phones":
      return products.filter((product) => product.category === "Phones" && product.isUkUsed);
    case "uk-used-laptops":
      return products.filter((product) => product.category === "Laptops" && product.isUkUsed);
    default:
      return products.filter((product) => product.category.toLowerCase() === categorySlug.toLowerCase());
  }
}
